/* Native draw readiness is independent of the credits' first-scroll pad gate. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-base.c"
#include "em_web_campaign.h"
static CPU c,before;static DuneMouse mouse;
static void check(int ok,const char*msg){if(!ok){fprintf(stderr,"FAIL %s %s\n",msg,em_web_campaign_report(&c));exit(1);}}
static void load(const char*path){FILE*f=fopen(path,"rb");check(f&&fread(&c,sizeof c,1,f)==1,"early native ending fixture");fclose(f);c.rom=rom_data;c.rom_size=sizeof rom_data;c.reason=NULL;c.fault=0;c.audio_mode=AUDIO_MUTE;c.pad_buttons[0]=0;memset(&mouse,0,sizeof mouse);mouse.enabled=1;memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&c);}
static void step(void){int audit=c.pc==0x11840||c.pc==0x11844||c.pc==0x127b4;if(audit)before=c;int handled=em_web_campaign_observe(&c);if(audit)check(!memcmp(&c,&before,sizeof c),"autoplay observer never mutates CPU");if(!handled)dune_mouse_observe(&mouse,&c);machine_step(&c);check(!c.fault,"native playback");}
int main(int argc,char**argv){check(argc>1,"usage EARLY_ENDING_FIXTURES...");for(int i=1;i<argc;i++){load(argv[i]);uint64_t first=c.vdp.frames,end=first+100;while(!em_web_campaign_scene_ready(&c)&&c.vdp.frames<end)step();check(em_web_campaign_scene_ready(&c)&&!strcmp(em_web_campaign.scene,"credits"),"early staff scroll is visible before first pad poll");check(c.vdp.frames-first<=4,"native credits draw readiness is prompt");check(!em_web_campaign.poll_generation&&!(c.d[4]&255),"first-scroll native input gate remains closed");const char*j=em_web_campaign_report(&c);check(strstr(j,"\"inputReady\":false")&&strstr(j,"\"sceneReady\":true"),"draw and input readiness are distinct");end=c.vdp.frames+100;while(c.vdp.frames<end)step();check(em_web_campaign_scene_ready(&c)&&!em_web_campaign.poll_generation&&!(c.d[4]&255),"native autoplay remains visible without granting skip");printf("PASS autoplay %s: early credits drawReady, inputReady false, native D4 closed, CPU immutable\n",argv[i]);fflush(stdout);}puts("PASS native autoplay completed-frame barrier without 90-second input wait");return 0;}
